import { Howl, Howler } from 'howler'
import { useGameStore } from './store.js'

export class AudioSystem {
  private sounds: Map<string, Howl> = new Map()
  private musicVolume = 0.7
  private sfxVolume = 0.8
  private muted = false

  constructor() {
    this.initializeSounds()
    this.setupStoreListener()
  }

  private initializeSounds(): void {
    // Create sounds with fallback to generated audio
    this.sounds.set('wing', new Howl({
      src: ['/assets/sounds/wing.wav'],
      volume: 0.5,
      onloaderror: () => {
        // Fallback to generated sound
        this.sounds.set('wing', this.createGeneratedSound('wing'))
      }
    }))

    this.sounds.set('hit', new Howl({
      src: ['/assets/sounds/hit.wav'],
      volume: 0.6,
      onloaderror: () => {
        this.sounds.set('hit', this.createGeneratedSound('hit'))
      }
    }))

    this.sounds.set('point', new Howl({
      src: ['/assets/sounds/point.wav'],
      volume: 0.7,
      onloaderror: () => {
        this.sounds.set('point', this.createGeneratedSound('point'))
      }
    }))

    this.sounds.set('die', new Howl({
      src: ['/assets/sounds/die.wav'],
      volume: 0.8,
      onloaderror: () => {
        this.sounds.set('die', this.createGeneratedSound('die'))
      }
    }))

    // Background music
    this.sounds.set('background', new Howl({
      src: ['/assets/sounds/background.mp3'],
      volume: 0.3,
      loop: true,
      onloaderror: () => {
        // No fallback for background music
      }
    }))
  }

  private createGeneratedSound(type: string): Howl {
    // Create Web Audio API generated sounds as fallback
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)()
    
    const createTone = (frequency: number, duration: number, type: OscillatorType = 'sine'): ArrayBuffer => {
      const sampleRate = audioContext.sampleRate
      const length = sampleRate * duration
      const buffer = audioContext.createBuffer(1, length, sampleRate)
      const data = buffer.getChannelData(0)
      
      for (let i = 0; i < length; i++) {
        const t = i / sampleRate
        let value = 0
        
        switch (type) {
          case 'sine':
            value = Math.sin(2 * Math.PI * frequency * t)
            break
          case 'square':
            value = Math.sin(2 * Math.PI * frequency * t) > 0 ? 1 : -1
            break
          case 'sawtooth':
            value = 2 * (t * frequency - Math.floor(t * frequency + 0.5))
            break
          case 'triangle':
            value = 2 * Math.abs(2 * (t * frequency - Math.floor(t * frequency + 0.5))) - 1
            break
        }
        
        // Apply envelope
        const envelope = Math.exp(-t * 3)
        data[i] = value * envelope * 0.1
      }
      
      return buffer.getChannelData(0).buffer
    }

    let soundData: ArrayBuffer
    
    switch (type) {
      case 'wing':
        soundData = createTone(200, 0.1, 'sine')
        break
      case 'hit':
        soundData = createTone(100, 0.3, 'square')
        break
      case 'point':
        soundData = createTone(600, 0.2, 'sine')
        break
      case 'die':
        soundData = createTone(150, 0.5, 'sawtooth')
        break
      default:
        soundData = createTone(440, 0.1, 'sine')
    }

    // Convert ArrayBuffer to Data URL (simplified)
    const dataUrl = 'data:audio/wav;base64,' + btoa(String.fromCharCode(...new Uint8Array(soundData)))
    
    return new Howl({
      src: [dataUrl],
      volume: 0.5,
      format: ['wav']
    })
  }

  private setupStoreListener(): void {
    const store = useGameStore.getState()
    
    // Subscribe to store changes
    useGameStore.subscribe((state) => {
      this.updateVolume(state.settings.audio.volume)
      this.setMuted(!state.settings.audio.enabled)
    })
    
    // Set initial state
    this.updateVolume(store.settings.audio.volume)
    this.setMuted(!store.settings.audio.enabled)
  }

  public playSound(key: string, volume?: number): void {
    if (this.muted) return
    
    const sound = this.sounds.get(key)
    if (sound) {
      if (volume !== undefined) {
        sound.volume(volume * this.sfxVolume)
      }
      sound.play()
    }
  }

  public stopSound(key: string): void {
    const sound = this.sounds.get(key)
    if (sound) {
      sound.stop()
    }
  }

  public pauseSound(key: string): void {
    const sound = this.sounds.get(key)
    if (sound) {
      sound.pause()
    }
  }

  public resumeSound(key: string): void {
    const sound = this.sounds.get(key)
    if (sound) {
      sound.play()
    }
  }

  public updateVolume(volume: number): void {
    this.musicVolume = volume
    this.sfxVolume = volume
    
    // Update all sound volumes
    this.sounds.forEach((sound, key) => {
      const vol = key === 'background' ? this.musicVolume : this.sfxVolume
      sound.volume(vol)
    })
  }

  public setMuted(muted: boolean): void {
    this.muted = muted
    Howler.mute(muted)
  }

  public isMuted(): boolean {
    return this.muted
  }

  public fadeIn(key: string, duration: number): void {
    const sound = this.sounds.get(key)
    if (sound) {
      sound.fade(0, this.musicVolume, duration)
    }
  }

  public fadeOut(key: string, duration: number): void {
    const sound = this.sounds.get(key)
    if (sound) {
      sound.fade(sound.volume(), 0, duration)
    }
  }

  public stopAllSounds(): void {
    this.sounds.forEach(sound => sound.stop())
  }

  public pauseAllSounds(): void {
    this.sounds.forEach(sound => sound.pause())
  }

  public resumeAllSounds(): void {
    this.sounds.forEach(sound => sound.play())
  }

  public preloadSounds(): Promise<void> {
    return new Promise((resolve) => {
      let loadedCount = 0
      const totalSounds = this.sounds.size
      
      if (totalSounds === 0) {
        resolve()
        return
      }
      
      this.sounds.forEach(sound => {
        sound.once('load', () => {
          loadedCount++
          if (loadedCount === totalSounds) {
            resolve()
          }
        })
        
        sound.once('loaderror', () => {
          loadedCount++
          if (loadedCount === totalSounds) {
            resolve()
          }
        })
      })
    })
  }

  public destroy(): void {
    this.sounds.forEach(sound => sound.unload())
    this.sounds.clear()
  }
}
