import type { 
  Bird, 
  Position, 
  Velocity, 
  CollisionBox 
} from '../types/index.js'
import { GAME_CONFIG, COLORS, clamp } from '../utils/helpers.js'
import { emit } from '../utils/events.js'

export class BirdComponent implements Bird {
  public position: Position
  public velocity: Velocity
  public size = { width: 34, height: 24 }
  public rotation = 0
  public isFlapping = false
  
  private readonly maxVelocity = 15
  private readonly jumpForce = GAME_CONFIG.jumpForce
  private readonly gravity = GAME_CONFIG.gravity
  private flapAnimation = 0
  private flapTimer = 0
  
  constructor(startX: number, startY: number) {
    this.position = { x: startX, y: startY }
    this.velocity = { x: 0, y: 0 }
  }

  public jump(): void {
    this.velocity.y = this.jumpForce
    this.isFlapping = true
    this.flapTimer = 200 // ms
    emit('bird-flap', { position: this.position })
  }

  public update(deltaTime: number): void {
    // Update flap animation
    if (this.isFlapping) {
      this.flapTimer -= deltaTime
      if (this.flapTimer <= 0) {
        this.isFlapping = false
      }
    }

    // Apply gravity
    this.velocity.y += this.gravity * deltaTime * 0.016 // Normalize to 60fps

    // Clamp velocity to prevent extreme speeds
    this.velocity.y = clamp(this.velocity.y, -this.maxVelocity, this.maxVelocity)

    // Update position
    this.position.y += this.velocity.y * deltaTime * 0.016

    // Update rotation based on velocity
    this.rotation = clamp(this.velocity.y * 0.05, -Math.PI / 6, Math.PI / 2)

    // Update flap animation
    this.flapAnimation += deltaTime * 0.01
    if (this.flapAnimation > Math.PI * 2) {
      this.flapAnimation = 0
    }
  }

  public render(context: CanvasRenderingContext2D): void {
    context.save()
    
    // Move to bird position
    context.translate(this.position.x + this.size.width / 2, this.position.y + this.size.height / 2)
    context.rotate(this.rotation)
    
    // Draw bird body
    context.fillStyle = COLORS.bird
    context.beginPath()
    context.ellipse(0, 0, this.size.width / 2, this.size.height / 2, 0, 0, Math.PI * 2)
    context.fill()
    
    // Draw bird eye
    context.fillStyle = '#000000'
    context.beginPath()
    context.ellipse(8, -4, 4, 4, 0, 0, Math.PI * 2)
    context.fill()
    
    // Draw bird beak
    context.fillStyle = '#ff9800'
    context.beginPath()
    context.moveTo(12, 0)
    context.lineTo(20, -3)
    context.lineTo(20, 3)
    context.closePath()
    context.fill()
    
    // Draw wing (animated)
    const wingOffset = Math.sin(this.flapAnimation * 8) * 2
    context.fillStyle = '#f57c00'
    context.beginPath()
    context.ellipse(-2, wingOffset, 8, 6, 0, 0, Math.PI * 2)
    context.fill()
    
    context.restore()
  }

  public getCollisionBox(): CollisionBox {
    return {
      x: this.position.x + 3,
      y: this.position.y + 3,
      width: this.size.width - 6,
      height: this.size.height - 6,
    }
  }

  public reset(x: number, y: number): void {
    this.position.x = x
    this.position.y = y
    this.velocity.x = 0
    this.velocity.y = 0
    this.rotation = 0
    this.isFlapping = false
    this.flapAnimation = 0
    this.flapTimer = 0
  }

  public isOutOfBounds(gameHeight: number): boolean {
    return this.position.y < -this.size.height || 
           this.position.y > gameHeight
  }

  public getSpeed(): number {
    return Math.sqrt(this.velocity.x ** 2 + this.velocity.y ** 2)
  }

  public setPosition(x: number, y: number): void {
    this.position.x = x
    this.position.y = y
  }

  public addVelocity(vx: number, vy: number): void {
    this.velocity.x += vx
    this.velocity.y += vy
  }
}
