import type { GameEvent, GameEventType } from '../types/index.js'

type EventListener<T = any> = (payload: T) => void

class EventEmitter {
  private listeners: Map<GameEventType, Set<EventListener>> = new Map()
  private eventQueue: GameEvent[] = []
  private isProcessing = false

  public on<T = any>(event: GameEventType, listener: EventListener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    this.listeners.get(event)!.add(listener)
  }

  public off<T = any>(event: GameEventType, listener: EventListener<T>): void {
    const eventListeners = this.listeners.get(event)
    if (eventListeners) {
      eventListeners.delete(listener)
      if (eventListeners.size === 0) {
        this.listeners.delete(event)
      }
    }
  }

  public emit(event: GameEventType, payload?: any): void {
    const gameEvent: GameEvent = {
      type: event,
      payload,
      timestamp: Date.now(),
    }

    this.eventQueue.push(gameEvent)
    
    if (!this.isProcessing) {
      this.processQueue()
    }
  }

  private processQueue(): void {
    this.isProcessing = true

    while (this.eventQueue.length > 0) {
      const event = this.eventQueue.shift()!
      const listeners = this.listeners.get(event.type)

      if (listeners) {
        listeners.forEach(listener => {
          try {
            listener(event.payload)
          } catch (error) {
            console.error(`Error in event listener for ${event.type}:`, error)
          }
        })
      }
    }

    this.isProcessing = false
  }

  public once<T = any>(event: GameEventType, listener: EventListener<T>): void {
    const onceListener = (payload: T) => {
      listener(payload)
      this.off(event, onceListener)
    }
    this.on(event, onceListener)
  }

  public removeAllListeners(event?: GameEventType): void {
    if (event) {
      this.listeners.delete(event)
    } else {
      this.listeners.clear()
    }
  }

  public hasListeners(event: GameEventType): boolean {
    return this.listeners.has(event) && this.listeners.get(event)!.size > 0
  }

  public getListenerCount(event: GameEventType): number {
    return this.listeners.get(event)?.size ?? 0
  }
}

// Singleton instance
export const eventEmitter = new EventEmitter()

// Helper functions
export const on = eventEmitter.on.bind(eventEmitter)
export const off = eventEmitter.off.bind(eventEmitter)
export const emit = eventEmitter.emit.bind(eventEmitter)
export const once = eventEmitter.once.bind(eventEmitter)
