// Utility functions
export const clamp = (value: number, min: number, max: number): number => {
  return Math.max(min, Math.min(max, value))
}

export const lerp = (start: number, end: number, factor: number): number => {
  return start + (end - start) * factor
}

export const randomBetween = (min: number, max: number): number => {
  return Math.random() * (max - min) + min
}

export const distance = (
  x1: number,
  y1: number,
  x2: number,
  y2: number
): number => {
  const dx = x2 - x1
  const dy = y2 - y1
  return Math.sqrt(dx * dx + dy * dy)
}

export const normalizeAngle = (angle: number): number => {
  while (angle > Math.PI) angle -= 2 * Math.PI
  while (angle < -Math.PI) angle += 2 * Math.PI
  return angle
}

export const degreesToRadians = (degrees: number): number => {
  return degrees * (Math.PI / 180)
}

export const radiansToDegrees = (radians: number): number => {
  return radians * (180 / Math.PI)
}

// Collision detection
export const isColliding = (box1: CollisionBox, box2: CollisionBox): boolean => {
  return (
    box1.x < box2.x + box2.width &&
    box1.x + box1.width > box2.x &&
    box1.y < box2.y + box2.height &&
    box1.y + box1.height > box2.y
  )
}

export const isPointInBox = (
  x: number,
  y: number,
  box: CollisionBox
): boolean => {
  return x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height
}

// Performance utilities
export const throttle = <T extends (...args: any[]) => any>(
  func: T,
  limit: number
): T => {
  let inThrottle: boolean
  return ((...args: Parameters<T>) => {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => (inThrottle = false), limit)
    }
  }) as T
}

export const debounce = <T extends (...args: any[]) => any>(
  func: T,
  delay: number
): T => {
  let timeoutId: ReturnType<typeof setTimeout>
  return ((...args: Parameters<T>) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => func(...args), delay)
  }) as T
}

// Storage utilities
export const saveToStorage = <T>(key: string, data: T): void => {
  try {
    localStorage.setItem(key, JSON.stringify(data))
  } catch (error) {
    console.warn('Failed to save to localStorage:', error)
  }
}

export const loadFromStorage = <T>(key: string, defaultValue: T): T => {
  try {
    const item = localStorage.getItem(key)
    return item ? JSON.parse(item) : defaultValue
  } catch (error) {
    console.warn('Failed to load from localStorage:', error)
    return defaultValue
  }
}

// Math utilities
export const easeInOutQuad = (t: number): number => {
  return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t
}

export const easeOutBounce = (t: number): number => {
  const n1 = 7.5625
  const d1 = 2.75

  if (t < 1 / d1) {
    return n1 * t * t
  } else if (t < 2 / d1) {
    return n1 * (t -= 1.5 / d1) * t + 0.75
  } else if (t < 2.5 / d1) {
    return n1 * (t -= 2.25 / d1) * t + 0.9375
  } else {
    return n1 * (t -= 2.625 / d1) * t + 0.984375
  }
}

// Time utilities
export const formatTime = (milliseconds: number): string => {
  const seconds = Math.floor(milliseconds / 1000)
  const minutes = Math.floor(seconds / 60)
  const remainingSeconds = seconds % 60
  
  return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`
}

export const getDeltaTime = (() => {
  let lastTime = 0
  return (currentTime: number): number => {
    const deltaTime = currentTime - lastTime
    lastTime = currentTime
    return deltaTime
  }
})()

// Validation utilities
export const isValidScore = (score: number): boolean => {
  return typeof score === 'number' && score >= 0 && Number.isInteger(score)
}

export const isValidPosition = (x: number, y: number): boolean => {
  return typeof x === 'number' && typeof y === 'number' && !isNaN(x) && !isNaN(y)
}
