import type { Background, Position } from '../types/index.js'
import { COLORS } from '../utils/helpers.js'

export class BackgroundComponent implements Background {
  public position: Position
  public speed: number
  
  private readonly groundHeight = 80
  private readonly cloudPositions: Position[] = []
  private readonly mountainPositions: Position[] = []
  
  private gameWidth: number
  private gameHeight: number
  
  constructor(gameWidth: number, gameHeight: number) {
    this.gameWidth = gameWidth
    this.gameHeight = gameHeight
    this.position = { x: 0, y: 0 }
    this.speed = 0.5
    
    // Initialize cloud positions
    this.initializeClouds()
    this.initializeMountains()
  }

  private initializeClouds(): void {
    for (let i = 0; i < 6; i++) {
      this.cloudPositions.push({
        x: (i * this.gameWidth) / 3,
        y: 50 + Math.random() * 100,
      })
    }
  }

  private initializeMountains(): void {
    for (let i = 0; i < 4; i++) {
      this.mountainPositions.push({
        x: (i * this.gameWidth) / 2,
        y: this.gameHeight - this.groundHeight - 100,
      })
    }
  }

  public update(deltaTime: number): void {
    // Move background elements
    this.position.x -= this.speed * deltaTime * 0.016
    
    // Update cloud positions
    this.cloudPositions.forEach(cloud => {
      cloud.x -= this.speed * deltaTime * 0.016
      if (cloud.x < -100) {
        cloud.x = this.gameWidth + 100
        cloud.y = 50 + Math.random() * 100
      }
    })
    
    // Update mountain positions
    this.mountainPositions.forEach(mountain => {
      mountain.x -= this.speed * 0.7 * deltaTime * 0.016
      if (mountain.x < -200) {
        mountain.x = this.gameWidth + 200
      }
    })
    
    // Reset background position for parallax effect
    if (this.position.x <= -this.gameWidth) {
      this.position.x = 0
    }
  }

  public render(context: CanvasRenderingContext2D): void {
    // Draw sky gradient
    this.drawSky(context)
    
    // Draw mountains
    this.drawMountains(context)
    
    // Draw clouds
    this.drawClouds(context)
    
    // Draw ground
    this.drawGround(context)
  }

  private drawSky(context: CanvasRenderingContext2D): void {
    const gradient = context.createLinearGradient(0, 0, 0, this.gameHeight)
    gradient.addColorStop(0, '#87CEEB')
    gradient.addColorStop(0.4, '#98D8E8')
    gradient.addColorStop(1, '#B0E0E6')
    
    context.fillStyle = gradient
    context.fillRect(0, 0, this.gameWidth, this.gameHeight)
  }

  private drawMountains(context: CanvasRenderingContext2D): void {
    context.fillStyle = '#8B7355'
    
    this.mountainPositions.forEach(mountain => {
      context.beginPath()
      context.moveTo(mountain.x, mountain.y + 100)
      context.lineTo(mountain.x + 60, mountain.y)
      context.lineTo(mountain.x + 120, mountain.y + 80)
      context.lineTo(mountain.x + 180, mountain.y + 40)
      context.lineTo(mountain.x + 240, mountain.y + 100)
      context.lineTo(mountain.x, mountain.y + 100)
      context.fill()
      
      // Add mountain highlights
      context.fillStyle = '#A0886B'
      context.beginPath()
      context.moveTo(mountain.x, mountain.y + 100)
      context.lineTo(mountain.x + 60, mountain.y)
      context.lineTo(mountain.x + 80, mountain.y + 20)
      context.lineTo(mountain.x + 20, mountain.y + 100)
      context.fill()
      
      context.fillStyle = '#8B7355'
    })
  }

  private drawClouds(context: CanvasRenderingContext2D): void {
    context.fillStyle = '#FFFFFF'
    
    this.cloudPositions.forEach(cloud => {
      this.drawCloud(context, cloud.x, cloud.y)
    })
  }

  private drawCloud(context: CanvasRenderingContext2D, x: number, y: number): void {
    context.beginPath()
    context.arc(x, y, 15, 0, Math.PI * 2)
    context.arc(x + 15, y - 5, 18, 0, Math.PI * 2)
    context.arc(x + 30, y, 15, 0, Math.PI * 2)
    context.arc(x + 35, y + 10, 12, 0, Math.PI * 2)
    context.arc(x + 20, y + 15, 14, 0, Math.PI * 2)
    context.arc(x + 5, y + 10, 12, 0, Math.PI * 2)
    context.fill()
  }

  private drawGround(context: CanvasRenderingContext2D): void {
    const groundY = this.gameHeight - this.groundHeight
    
    // Draw ground gradient
    const gradient = context.createLinearGradient(0, groundY, 0, this.gameHeight)
    gradient.addColorStop(0, COLORS.ground)
    gradient.addColorStop(1, '#689F38')
    
    context.fillStyle = gradient
    context.fillRect(0, groundY, this.gameWidth, this.groundHeight)
    
    // Draw grass details
    context.fillStyle = '#7CB342'
    for (let x = 0; x < this.gameWidth; x += 20) {
      const grassX = x + (this.position.x % 20)
      context.fillRect(grassX, groundY, 2, 8)
      context.fillRect(grassX + 5, groundY, 2, 6)
      context.fillRect(grassX + 10, groundY, 2, 7)
      context.fillRect(grassX + 15, groundY, 2, 5)
    }
  }

  public getGroundHeight(): number {
    return this.groundHeight
  }

  public getGroundY(): number {
    return this.gameHeight - this.groundHeight
  }

  public isOnGround(y: number, objectHeight: number): boolean {
    return y + objectHeight >= this.getGroundY()
  }

  public reset(): void {
    this.position.x = 0
    this.position.y = 0
    this.initializeClouds()
    this.initializeMountains()
  }

  public setSpeed(speed: number): void {
    this.speed = speed
  }

  public getParallaxOffset(): number {
    return this.position.x * 0.3
  }
}
