import './style.css'
import { GameManager } from './utils/gameManager.js'
import { GAME_CONFIG } from './utils/helpers.js'

// Initialize the game
async function initializeGame(): Promise<void> {
  // Hide loading screen
  const loadingElement = document.getElementById('loading')
  
  try {
    // Get the game container
    const gameContainer = document.getElementById('game-container')
    if (!gameContainer) {
      throw new Error('Game container not found')
    }
    
    // Create canvas
    const canvas = document.createElement('canvas')
    canvas.width = GAME_CONFIG.width
    canvas.height = GAME_CONFIG.height
    canvas.style.display = 'block'
    canvas.style.imageRendering = 'pixelated'
    
    // Add canvas to container
    gameContainer.appendChild(canvas)
    
    // Create game manager
    const gameManager = new GameManager(canvas)
    
    // Start the game loop
    gameManager.start()
    
    // Hide loading screen
    if (loadingElement) {
      loadingElement.style.display = 'none'
    }
    
    // Add keyboard focus to canvas
    canvas.focus()
    canvas.setAttribute('tabindex', '0')
    
    // Add game info to window for debugging
    if (import.meta.env.DEV) {
      (window as any).gameManager = gameManager
      console.log('🎮 Flappy Bird initialized successfully!')
      console.log('🎯 Game controls:')
      console.log('  - Space/Click: Jump')
      console.log('  - P: Pause/Resume')
      console.log('  - R: Restart (when game over)')
    }
    
  } catch (error) {
    console.error('❌ Failed to initialize game:', error)
    
    // Show error message
    if (loadingElement) {
      loadingElement.innerHTML = `
        <div style="color: #ff6b6b; text-align: center;">
          <h2>Error Loading Game</h2>
          <p>${error instanceof Error ? error.message : 'Unknown error'}</p>
          <button onclick="location.reload()" style="
            background: #4ecdc4;
            color: white;
            border: none;
            padding: 10px 20px;
            border-radius: 5px;
            cursor: pointer;
            font-size: 16px;
            margin-top: 20px;
          ">
            Reload Game
          </button>
        </div>
      `
    }
  }
}

// Initialize when DOM is loaded
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeGame)
} else {
  initializeGame()
}

// Handle page visibility changes
document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    // Page is hidden, pause game
    window.dispatchEvent(new Event('blur'))
  } else {
    // Page is visible, resume game
    window.dispatchEvent(new Event('focus'))
  }
})

// Handle errors
window.addEventListener('error', (event) => {
  console.error('🔥 Global error:', event.error)
})

window.addEventListener('unhandledrejection', (event) => {
  console.error('🔥 Unhandled promise rejection:', event.reason)
  event.preventDefault()
})
