import type { 
  Pipe, 
  Position, 
  Size, 
  CollisionBox 
} from '../types/index.js'
import { GAME_CONFIG, COLORS, randomBetween } from '../utils/helpers.js'

export class PipeComponent implements Pipe {
  public id: string
  public position: Position
  public size: Size
  public passed = false
  public gap: number
  
  private readonly speed = GAME_CONFIG.pipeSpeed
  private readonly minGapY = 100
  private readonly maxGapY = 400
  
  constructor(x: number, gameHeight: number) {
    this.id = `pipe-${Date.now()}-${Math.random()}`
    this.position = { x, y: 0 }
    this.size = { width: 52, height: gameHeight }
    this.gap = GAME_CONFIG.pipeGap
    
    // Random gap position
    const gapY = randomBetween(this.minGapY, this.maxGapY)
    this.position.y = gapY - this.gap / 2
  }

  public update(deltaTime: number): void {
    // Move pipe to the left
    this.position.x -= this.speed * deltaTime * 0.016
  }

  public render(context: CanvasRenderingContext2D): void {
    const pipeWidth = this.size.width
    const topPipeHeight = this.position.y
    const bottomPipeY = this.position.y + this.gap
    const bottomPipeHeight = this.size.height - bottomPipeY
    
    // Draw top pipe
    context.fillStyle = COLORS.pipe
    context.fillRect(this.position.x, 0, pipeWidth, topPipeHeight)
    
    // Draw top pipe cap
    context.fillStyle = '#2e7d32'
    context.fillRect(this.position.x - 4, topPipeHeight - 30, pipeWidth + 8, 30)
    
    // Draw bottom pipe
    context.fillStyle = COLORS.pipe
    context.fillRect(this.position.x, bottomPipeY, pipeWidth, bottomPipeHeight)
    
    // Draw bottom pipe cap
    context.fillStyle = '#2e7d32'
    context.fillRect(this.position.x - 4, bottomPipeY, pipeWidth + 8, 30)
    
    // Add pipe details
    this.drawPipeDetails(context, this.position.x, 0, pipeWidth, topPipeHeight)
    this.drawPipeDetails(context, this.position.x, bottomPipeY, pipeWidth, bottomPipeHeight)
  }

  private drawPipeDetails(
    context: CanvasRenderingContext2D, 
    x: number, 
    y: number, 
    width: number, 
    height: number
  ): void {
    // Draw pipe highlights
    context.fillStyle = '#66bb6a'
    context.fillRect(x + 4, y + 4, 4, height - 8)
    context.fillRect(x + width - 8, y + 4, 4, height - 8)
    
    // Draw pipe shadows
    context.fillStyle = '#388e3c'
    context.fillRect(x + 12, y + 4, 2, height - 8)
    context.fillRect(x + width - 14, y + 4, 2, height - 8)
  }

  public getCollisionBoxes(): CollisionBox[] {
    const topPipeHeight = this.position.y
    const bottomPipeY = this.position.y + this.gap
    const bottomPipeHeight = this.size.height - bottomPipeY
    
    return [
      // Top pipe
      {
        x: this.position.x,
        y: 0,
        width: this.size.width,
        height: topPipeHeight,
      },
      // Bottom pipe
      {
        x: this.position.x,
        y: bottomPipeY,
        width: this.size.width,
        height: bottomPipeHeight,
      },
    ]
  }

  public isOffScreen(): boolean {
    return this.position.x + this.size.width < 0
  }

  public isInScoreZone(birdX: number): boolean {
    return !this.passed && 
           birdX > this.position.x + this.size.width / 2 &&
           birdX < this.position.x + this.size.width
  }

  public getGapCenter(): Position {
    return {
      x: this.position.x + this.size.width / 2,
      y: this.position.y + this.gap / 2,
    }
  }

  public distanceToCenter(birdPosition: Position): number {
    const gapCenter = this.getGapCenter()
    const dx = gapCenter.x - birdPosition.x
    const dy = gapCenter.y - birdPosition.y
    return Math.sqrt(dx * dx + dy * dy)
  }

  public getDifficulty(): number {
    // Smaller gap = higher difficulty
    return 1 - (this.gap / 200)
  }

  public adjustDifficulty(difficulty: number): void {
    // Adjust gap size based on difficulty (1-3 scale)
    const baseGap = GAME_CONFIG.pipeGap
    const minGap = 100
    const maxGap = 200
    
    this.gap = Math.max(minGap, Math.min(maxGap, baseGap - (difficulty - 1) * 30))
  }
}
