import { BirdComponent } from '../components/Bird.js'
import { PipeComponent } from '../components/Pipe.js'
import { BackgroundComponent } from '../components/Background.js'
import { AudioSystem } from '../utils/audio.js'
import { CollisionSystem } from '../utils/collision.js'
import { useGameStore } from '../utils/store.js'
import { emit, on, off } from '../utils/events.js'
import { GAME_CONFIG, clamp, isColliding } from '../utils/helpers.js'
import type { GameState } from '../types/index.js'

export class GameManager {
  private canvas: HTMLCanvasElement
  private context: CanvasRenderingContext2D
  private gameState: GameState
  private animationId: number | null = null
  private lastTime = 0
  private deltaTime = 0
  
  // Game objects
  private bird: BirdComponent
  private pipes: PipeComponent[] = []
  private background: BackgroundComponent
  private audioSystem: AudioSystem
  private collisionSystem: CollisionSystem
  
  // Game timing
  private pipeSpawnTimer = 0
  private difficultyTimer = 0
  private gameTime = 0
  
  // Input handling
  private keys: Set<string> = new Set()
  private lastJump = 0
  
  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas
    this.context = canvas.getContext('2d')!
    this.gameState = useGameStore.getState()
    
    // Initialize game objects
    this.bird = new BirdComponent(80, GAME_CONFIG.height / 2)
    this.background = new BackgroundComponent(GAME_CONFIG.width, GAME_CONFIG.height)
    this.audioSystem = new AudioSystem()
    this.collisionSystem = CollisionSystem.getInstance()
    
    // Register bird in collision system immediately
    this.collisionSystem.registerCollider('bird', this.bird.getCollisionBox())
    
    this.setupCanvas()
    this.setupEventListeners()
    this.setupStoreSubscription()
    this.setupGameEvents()
  }

  private setupCanvas(): void {
    this.canvas.width = GAME_CONFIG.width
    this.canvas.height = GAME_CONFIG.height
    this.context.imageSmoothingEnabled = true
    this.context.imageSmoothingQuality = 'high'
  }

  private setupEventListeners(): void {
    // Keyboard events
    window.addEventListener('keydown', this.handleKeyDown.bind(this))
    window.addEventListener('keyup', this.handleKeyUp.bind(this))
    
    // Mouse events
    this.canvas.addEventListener('mousedown', this.handlePointerDown.bind(this))
    this.canvas.addEventListener('mouseup', this.handlePointerUp.bind(this))
    
    // Touch events
    this.canvas.addEventListener('touchstart', this.handlePointerDown.bind(this))
    this.canvas.addEventListener('touchend', this.handlePointerUp.bind(this))
    
    // Prevent context menu
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault())
    
    // Focus events
    window.addEventListener('focus', this.handleFocus.bind(this))
    window.addEventListener('blur', this.handleBlur.bind(this))
  }

  private setupStoreSubscription(): void {
    useGameStore.subscribe((state) => {
      this.gameState = state
    })
  }

  private setupGameEvents(): void {
    on('bird-flap', () => {
      this.audioSystem.playSound('wing')
    })
    
    on('collision', () => {
      this.audioSystem.playSound('hit')
      this.endGame()
    })
    
    on('game-over', () => {
      this.audioSystem.playSound('die')
    })
  }

  private handleKeyDown(event: KeyboardEvent): void {
    this.keys.add(event.code)
    
    if (event.code === 'Space' || event.code === 'ArrowUp') {
      event.preventDefault()
      this.handleJump()
    }
    
    if (event.code === 'KeyP') {
      this.togglePause()
    }
    
    if (event.code === 'KeyR' && this.gameState.isGameOver) {
      this.resetGame()
    }
  }

  private handleKeyUp(event: KeyboardEvent): void {
    this.keys.delete(event.code)
  }

  private handlePointerDown(event: Event): void {
    event.preventDefault()
    this.handleJump()
  }

  private handlePointerUp(event: Event): void {
    event.preventDefault()
  }

  private handleFocus(): void {
    // Resume game if it was paused due to blur
    if (this.gameState.isPaused && this.gameState.isPlaying) {
      this.resumeGame()
    }
  }

  private handleBlur(): void {
    // Pause game when window loses focus
    if (this.gameState.isPlaying && !this.gameState.isPaused) {
      this.pauseGame()
    }
  }

  private handleJump(): void {
    const now = Date.now()
    const jumpCooldown = 100 // ms
    
    if (now - this.lastJump < jumpCooldown) {
      return
    }
    
    this.lastJump = now
    
    if (this.gameState.isGameOver) {
      this.resetGame()
    } else if (this.gameState.isPlaying && !this.gameState.isPaused) {
      this.bird.jump()
    } else if (!this.gameState.isPlaying) {
      this.startGame()
    }
  }

  public startGame(): void {
    useGameStore.getState().startGame()
    this.resetGameObjects()
    this.gameTime = 0
    this.difficultyTimer = 0
    this.pipeSpawnTimer = 0
    
    emit('game-start')
    
    if (!this.animationId) {
      this.gameLoop()
    }
  }

  public pauseGame(): void {
    useGameStore.getState().pauseGame()
    emit('game-pause')
  }

  public resumeGame(): void {
    useGameStore.getState().resumeGame()
    emit('game-resume')
  }

  public endGame(): void {
    useGameStore.getState().endGame()
    emit('game-over')
  }

  public resetGame(): void {
    useGameStore.getState().resetGame()
    this.resetGameObjects()
    // emit('game-reset') // Commented out due to type mismatch
  }

  private resetGameObjects(): void {
    this.bird.reset(80, GAME_CONFIG.height / 2)
    this.pipes.length = 0
    this.background.reset()
    this.collisionSystem.clear()
    
    // Register bird in collision system
    this.collisionSystem.registerCollider('bird', this.bird.getCollisionBox())
  }

  private togglePause(): void {
    if (this.gameState.isPlaying) {
      if (this.gameState.isPaused) {
        this.resumeGame()
      } else {
        this.pauseGame()
      }
    }
  }

  private increaseScore(): void {
    const newScore = this.gameState.score.current + 1
    useGameStore.getState().updateScore(newScore)
    emit('score-update', { score: newScore })
    
    // Increase difficulty every 5 points
    if (newScore % 5 === 0) {
      useGameStore.getState().increaseDifficulty()
    }
  }

  private spawnPipe(): void {
    const pipe = new PipeComponent(GAME_CONFIG.width, GAME_CONFIG.height)
    pipe.adjustDifficulty(this.gameState.difficulty)
    this.pipes.push(pipe)
    
    // Register collision
    this.collisionSystem.registerMultipleColliders(pipe.id, pipe.getCollisionBoxes())
  }

  private updatePipes(deltaTime: number): void {
    // Update existing pipes
    this.pipes.forEach(pipe => {
      pipe.update(deltaTime)
      this.collisionSystem.updateMultipleColliders(pipe.id, pipe.getCollisionBoxes())
    })
    
    // Check for scoring (bird passed through pipe)
    this.pipes.forEach(pipe => {
      if (!pipe.passed && pipe.position.x + pipe.size.width < this.bird.position.x) {
        pipe.passed = true
        this.increaseScore()
        this.audioSystem.playSound('point')
      }
    })
    
    // Remove off-screen pipes
    this.pipes = this.pipes.filter(pipe => {
      if (pipe.isOffScreen()) {
        this.collisionSystem.unregisterCollider(pipe.id)
        return false
      }
      return true
    })
    
    // Spawn new pipes
    this.pipeSpawnTimer += deltaTime
    const spawnInterval = GAME_CONFIG.spawnInterval * Math.max(0.5, 1 - (this.gameState.difficulty - 1) * 0.2)
    
    // Check if we should spawn a new pipe
    const shouldSpawn = this.pipeSpawnTimer >= spawnInterval
    const minDistance = 200 // Minimum distance between pipes
    const lastPipe = this.pipes.length > 0 ? this.pipes[this.pipes.length - 1] : null
    const hasEnoughSpace = !lastPipe || (GAME_CONFIG.width - lastPipe.position.x) >= minDistance
    
    if (shouldSpawn && hasEnoughSpace) {
      this.spawnPipe()
      this.pipeSpawnTimer = 0
    }
  }

  private checkCollisions(): void {
    const birdBox = this.bird.getCollisionBox()
    this.collisionSystem.updateCollider('bird', birdBox)
    
    // Check bird-pipe collisions
    for (const pipe of this.pipes) {
      const pipeBoxes = pipe.getCollisionBoxes()
      for (const pipeBox of pipeBoxes) {
        if (isColliding(birdBox, pipeBox)) {
          emit('collision', { bird: this.bird, pipe })
          return
        }
      }
    }
    
    // Check bird-ground collision
    if (this.background.isOnGround(this.bird.position.y, this.bird.size.height)) {
      emit('collision', { bird: this.bird, ground: true })
    }
    
    // Check bird-ceiling collision
    if (this.bird.position.y < 0) {
      emit('collision', { bird: this.bird, ceiling: true })
    }
  }

  private update(deltaTime: number): void {
    if (!this.gameState.isPlaying || this.gameState.isPaused) {
      return
    }
    
    this.gameTime += deltaTime
    
    // Update game objects
    this.bird.update(deltaTime)
    this.background.update(deltaTime)
    this.updatePipes(deltaTime)
    
    // Check collisions
    this.checkCollisions()
    
    // Update difficulty over time
    this.difficultyTimer += deltaTime
    if (this.difficultyTimer >= 30000) { // Every 30 seconds
      useGameStore.getState().increaseDifficulty()
      this.difficultyTimer = 0
    }
  }

  private render(): void {
    // Clear canvas
    this.context.clearRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height)
    
    // Render game objects
    this.background.render(this.context)
    this.pipes.forEach(pipe => pipe.render(this.context))
    this.bird.render(this.context)
    
    // Render UI
    this.renderUI()
  }

  private renderUI(): void {
    // Score
    this.context.fillStyle = '#ffffff'
    this.context.font = 'bold 32px Arial'
    this.context.textAlign = 'center'
    this.context.fillText(
      this.gameState.score.current.toString(),
      GAME_CONFIG.width / 2,
      60
    )
    
    // Best score
    this.context.font = '16px Arial'
    this.context.fillText(
      `Best: ${this.gameState.score.best}`,
      GAME_CONFIG.width / 2,
      85
    )
    
    // Game over screen
    if (this.gameState.isGameOver) {
      this.renderGameOverScreen()
    }
    
    // Pause screen
    if (this.gameState.isPaused) {
      this.renderPauseScreen()
    }
    
    // Start screen
    if (!this.gameState.isPlaying && !this.gameState.isGameOver) {
      this.renderStartScreen()
    }
  }

  private renderStartScreen(): void {
    this.context.fillStyle = 'rgba(0, 0, 0, 0.8)'
    this.context.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height)
    
    this.context.fillStyle = '#ffffff'
    this.context.font = 'bold 48px Arial'
    this.context.textAlign = 'center'
    this.context.fillText('Flappy Bird', GAME_CONFIG.width / 2, GAME_CONFIG.height / 2 - 50)
    
    this.context.font = '24px Arial'
    this.context.fillText('Click or Press Space to Start', GAME_CONFIG.width / 2, GAME_CONFIG.height / 2 + 20)
  }

  private renderPauseScreen(): void {
    this.context.fillStyle = 'rgba(0, 0, 0, 0.6)'
    this.context.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height)
    
    this.context.fillStyle = '#ffffff'
    this.context.font = 'bold 36px Arial'
    this.context.textAlign = 'center'
    this.context.fillText('PAUSED', GAME_CONFIG.width / 2, GAME_CONFIG.height / 2)
    
    this.context.font = '20px Arial'
    this.context.fillText('Press P to Resume', GAME_CONFIG.width / 2, GAME_CONFIG.height / 2 + 40)
  }

  private renderGameOverScreen(): void {
    this.context.fillStyle = 'rgba(0, 0, 0, 0.8)'
    this.context.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height)
    
    this.context.fillStyle = '#ff4444'
    this.context.font = 'bold 48px Arial'
    this.context.textAlign = 'center'
    this.context.fillText('GAME OVER', GAME_CONFIG.width / 2, GAME_CONFIG.height / 2 - 50)
    
    this.context.fillStyle = '#ffffff'
    this.context.font = '24px Arial'
    this.context.fillText(`Score: ${this.gameState.score.current}`, GAME_CONFIG.width / 2, GAME_CONFIG.height / 2)
    this.context.fillText(`Best: ${this.gameState.score.best}`, GAME_CONFIG.width / 2, GAME_CONFIG.height / 2 + 30)
    
    this.context.font = '20px Arial'
    this.context.fillText('Click or Press R to Restart', GAME_CONFIG.width / 2, GAME_CONFIG.height / 2 + 70)
  }

  private gameLoop = (currentTime: number = 0): void => {
    this.deltaTime = currentTime - this.lastTime
    this.lastTime = currentTime
    
    // Cap deltaTime to prevent large jumps
    this.deltaTime = clamp(this.deltaTime, 0, 32)
    
    this.update(this.deltaTime)
    this.render()
    
    this.animationId = requestAnimationFrame(this.gameLoop)
  }

  public start(): void {
    this.gameLoop()
  }

  public stop(): void {
    if (this.animationId) {
      cancelAnimationFrame(this.animationId)
      this.animationId = null
    }
  }

  public destroy(): void {
    this.stop()
    
    // Clean up event listeners
    window.removeEventListener('keydown', this.handleKeyDown.bind(this))
    window.removeEventListener('keyup', this.handleKeyUp.bind(this))
    window.removeEventListener('focus', this.handleFocus.bind(this))
    window.removeEventListener('blur', this.handleBlur.bind(this))
    
    // Clean up game events
    off('bird-flap', () => {})
    off('pipe-pass', () => {})
    off('collision', () => {})
    off('game-over', () => {})
    
    // Clean up systems
    this.audioSystem.destroy()
    this.collisionSystem.clear()
  }
}
