import type { CollisionBox } from '../types/index.js'
import { isColliding } from './helpers.js'

export interface CollisionResult {
  collided: boolean
  overlap: {
    x: number
    y: number
  }
  normal: {
    x: number
    y: number
  }
}

export class CollisionSystem {
  private static instance: CollisionSystem
  private collisionPairs: Map<string, CollisionBox[]> = new Map()
  private collisionCallbacks: Map<string, (result: CollisionResult) => void> = new Map()

  public static getInstance(): CollisionSystem {
    if (!CollisionSystem.instance) {
      CollisionSystem.instance = new CollisionSystem()
    }
    return CollisionSystem.instance
  }

  public registerCollider(id: string, box: CollisionBox): void {
    this.collisionPairs.set(id, [box])
  }

  public registerMultipleColliders(id: string, boxes: CollisionBox[]): void {
    this.collisionPairs.set(id, boxes)
  }

  public unregisterCollider(id: string): void {
    this.collisionPairs.delete(id)
    this.collisionCallbacks.delete(id)
  }

  public setCollisionCallback(id: string, callback: (result: CollisionResult) => void): void {
    this.collisionCallbacks.set(id, callback)
  }

  public checkCollision(id1: string, id2: string): CollisionResult {
    const boxes1 = this.collisionPairs.get(id1)
    const boxes2 = this.collisionPairs.get(id2)

    if (!boxes1 || !boxes2) {
      return { collided: false, overlap: { x: 0, y: 0 }, normal: { x: 0, y: 0 } }
    }

    // Check all box combinations
    for (const box1 of boxes1) {
      for (const box2 of boxes2) {
        const result = this.checkBoxCollision(box1, box2)
        if (result.collided) {
          return result
        }
      }
    }

    return { collided: false, overlap: { x: 0, y: 0 }, normal: { x: 0, y: 0 } }
  }

  private checkBoxCollision(box1: CollisionBox, box2: CollisionBox): CollisionResult {
    if (!isColliding(box1, box2)) {
      return { collided: false, overlap: { x: 0, y: 0 }, normal: { x: 0, y: 0 } }
    }

    // Calculate overlap
    const overlapX = Math.min(box1.x + box1.width, box2.x + box2.width) - Math.max(box1.x, box2.x)
    const overlapY = Math.min(box1.y + box1.height, box2.y + box2.height) - Math.max(box1.y, box2.y)

    // Calculate collision normal
    const centerX1 = box1.x + box1.width / 2
    const centerY1 = box1.y + box1.height / 2
    const centerX2 = box2.x + box2.width / 2
    const centerY2 = box2.y + box2.height / 2

    const dx = centerX2 - centerX1
    const dy = centerY2 - centerY1
    const distance = Math.sqrt(dx * dx + dy * dy)

    let normalX = 0
    let normalY = 0

    if (distance > 0) {
      normalX = dx / distance
      normalY = dy / distance
    }

    return {
      collided: true,
      overlap: { x: overlapX, y: overlapY },
      normal: { x: normalX, y: normalY }
    }
  }

  public checkAllCollisions(): void {
    const ids = Array.from(this.collisionPairs.keys())
    
    for (let i = 0; i < ids.length; i++) {
      for (let j = i + 1; j < ids.length; j++) {
        const id1 = ids[i]
        const id2 = ids[j]
        
        if (id1 && id2) {
          const result = this.checkCollision(id1, id2)
          
          if (result.collided) {
            // Call callbacks for both objects
            const callback1 = this.collisionCallbacks.get(id1)
            const callback2 = this.collisionCallbacks.get(id2)
            
            if (callback1) {
              callback1(result)
            }
            
            if (callback2) {
              // Invert normal for the second object
              const invertedResult = {
                ...result,
                normal: { x: -result.normal.x, y: -result.normal.y }
              }
              callback2(invertedResult)
            }
          }
        }
      }
    }
  }

  public updateCollider(id: string, box: CollisionBox): void {
    if (this.collisionPairs.has(id)) {
      this.collisionPairs.set(id, [box])
    }
  }

  public updateMultipleColliders(id: string, boxes: CollisionBox[]): void {
    if (this.collisionPairs.has(id)) {
      this.collisionPairs.set(id, boxes)
    }
  }

  public isPointInCollider(id: string, x: number, y: number): boolean {
    const boxes = this.collisionPairs.get(id)
    if (!boxes) return false

    for (const box of boxes) {
      if (x >= box.x && x <= box.x + box.width && 
          y >= box.y && y <= box.y + box.height) {
        return true
      }
    }

    return false
  }

  public getColliderBounds(id: string): CollisionBox | null {
    const boxes = this.collisionPairs.get(id)
    if (!boxes || boxes.length === 0) return null

    if (boxes.length === 1) {
      return boxes[0] || null
    }

    // Calculate bounding box for multiple colliders
    let minX = Infinity
    let minY = Infinity
    let maxX = -Infinity
    let maxY = -Infinity

    for (const box of boxes) {
      minX = Math.min(minX, box.x)
      minY = Math.min(minY, box.y)
      maxX = Math.max(maxX, box.x + box.width)
      maxY = Math.max(maxY, box.y + box.height)
    }

    return {
      x: minX,
      y: minY,
      width: maxX - minX,
      height: maxY - minY
    }
  }

  public getColliderCount(): number {
    return this.collisionPairs.size
  }

  public clear(): void {
    this.collisionPairs.clear()
    this.collisionCallbacks.clear()
  }

  public debugRender(context: CanvasRenderingContext2D): void {
    context.strokeStyle = '#ff0000'
    context.lineWidth = 2

    this.collisionPairs.forEach(boxes => {
      boxes.forEach(box => {
        context.strokeRect(box.x, box.y, box.width, box.height)
      })
    })
  }
}
