import { create } from 'zustand'
import { persist, createJSONStorage } from 'zustand/middleware'
import type { GameState, GameSettings, AudioConfig } from '../types/index.js'

interface GameStore extends GameState {
  settings: GameSettings
  // Actions
  startGame: () => void
  endGame: () => void
  pauseGame: () => void
  resumeGame: () => void
  updateScore: (score: number) => void
  resetGame: () => void
  updateSettings: (settings: Partial<GameSettings>) => void
  updateAudioSettings: (audio: Partial<AudioConfig>) => void
  increaseDifficulty: () => void
}

const initialState: GameState = {
  isPlaying: false,
  isGameOver: false,
  isPaused: false,
  score: {
    current: 0,
    best: 0,
  },
  difficulty: 1,
}

const initialSettings: GameSettings = {
  audio: {
    enabled: true,
    volume: 0.7,
  },
  graphics: {
    quality: 'high',
    effects: true,
  },
  controls: {
    sensitivity: 1,
    touchEnabled: true,
  },
}

export const useGameStore = create<GameStore>()(
  persist(
    (set, get) => ({
      ...initialState,
      settings: initialSettings,

      startGame: () => {
        set({
          isPlaying: true,
          isGameOver: false,
          isPaused: false,
          score: { ...get().score, current: 0 },
        })
      },

      endGame: () => {
        const { score } = get()
        const newBest = Math.max(score.current, score.best)
        
        set({
          isPlaying: false,
          isGameOver: true,
          isPaused: false,
          score: { ...score, best: newBest },
        })
      },

      pauseGame: () => {
        if (get().isPlaying) {
          set({ isPaused: true })
        }
      },

      resumeGame: () => {
        if (get().isPlaying) {
          set({ isPaused: false })
        }
      },

      updateScore: (newScore: number) => {
        set(state => ({
          score: { ...state.score, current: newScore },
        }))
      },

      resetGame: () => {
        set({
          ...initialState,
          score: { current: 0, best: get().score.best },
        })
      },

      updateSettings: (newSettings: Partial<GameSettings>) => {
        set(state => ({
          settings: { ...state.settings, ...newSettings },
        }))
      },

      updateAudioSettings: (audioSettings: Partial<AudioConfig>) => {
        set(state => ({
          settings: {
            ...state.settings,
            audio: { ...state.settings.audio, ...audioSettings },
          },
        }))
      },

      increaseDifficulty: () => {
        set(state => ({
          difficulty: Math.min(state.difficulty + 0.1, 3),
        }))
      },
    }),
    {
      name: 'flappy-bird-game-store',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        score: { current: 0, best: state.score.best },
        settings: state.settings,
      }),
    }
  )
)
